// Portfolios page — the three candidate versions (Endowment / SAA / DAA-MRS) from the
// progression research, rendered from data/candidates.js (generated by
// Src/build_portfolios_dashboard_data.py — nothing on this page is hand-typed data).
// Self-contained: does not load app.js (that file renders the superseded book's payload).

/* global Plotly, CANDIDATES */
(function () {
  const D = window.PORTFOLIOS;
  const el = (id) => document.getElementById(id);
  if (!D) { el("appbar-status").textContent = "portfolios.js data missing"; return; }

  // ---------- shared style (mirrors app.js conventions) ----------
  const FONT = { family: "-apple-system, Segoe UI, Roboto, sans-serif", size: 11, color: "#46535f" };
  const BASE = { font: FONT, margin: { l: 42, r: 14, t: 8, b: 30 }, paper_bgcolor: "transparent",
    plot_bgcolor: "transparent", separators: ".,",
    hoverlabel: { bgcolor: "#ffffff", bordercolor: "#dbe2ea", font: { size: 11, color: "#1b2733" }, align: "left" },
    xaxis: { gridcolor: "#eff2f6", zeroline: false, linecolor: "#e3e8ee", ticks: "", tickfont: { size: 10 } },
    yaxis: { gridcolor: "#eff2f6", zeroline: false, linecolor: "#e3e8ee", ticks: "", tickfont: { size: 10 } } };
  const CFG = { displayModeBar: false, responsive: true };
  const fmtPct = (x, d = 1) => (x >= 0 ? "" : "−") + Math.abs(x).toFixed(d) + "%";
  const fmtSign = (x, suf = "%", d = 1) => (x >= 0 ? "+" : "−") + Math.abs(x).toFixed(d) + suf;

  const BOOKS = D.books;
  const BOOK3 = D.order;                       // the five portfolios, in registry order
  const ANCHOR = "acwi6040";                   // the balanced benchmark the family is judged against
  const bestSharpe = BOOK3.reduce((a, b) => (D.metrics[b].sharpe > D.metrics[a].sharpe ? b : a));
  const shallowest = BOOK3.reduce((a, b) => (D.metrics[b].mdd > D.metrics[a].mdd ? b : a));
  const richest = BOOK3.reduce((a, b) => (D.metrics[b].cagr > D.metrics[a].cagr ? b : a));
  const SLEEVES = ["Equities", "FixedIncome", "Commodities", "RealEstate", "Cash", "AltsInsurance"];
  const SLEEVE_META = {
    Equities:      { label: "Equities",       color: "#1f5e8f" },
    FixedIncome:   { label: "Fixed Income",   color: "#54a07d" },
    Commodities:   { label: "Commodities",    color: "#c9932b" },
    RealEstate:    { label: "Real Estate",    color: "#5aa6d4" },
    Cash:          { label: "Cash",           color: "#8b97a3" },
    AltsInsurance: { label: "Alts/Insurance", color: "#7a5c96" },
    SPY_satellite: { label: "SPY satellite",  color: "#0e2233" },
  };
  const REGIMES = ["Expansion", "Neutral", "Slowdown", "Contraction"];
  const REGIME_SHADE = { Expansion: "rgba(46,125,50,0.10)", Neutral: "rgba(48,131,180,0.07)",
    Slowdown: "rgba(214,138,19,0.13)", Contraction: "rgba(192,57,43,0.14)" };
  const REGIME_STANCE = { Expansion: "advance", Neutral: "participate", Slowdown: "defend", Contraction: "defend" };

  const dates = D.series.dates.map((d) => d + "-01");
  const M = D.metrics;
  const p = (x, d = 1) => fmtPct(x * 100, d);

  // crisis bands from the payload's own episodes (not hardcoded)
  function crisisOverlay() {
    const shapes = [], annotations = [];
    for (const c of D.crises) {
      shapes.push({ type: "rect", xref: "x", yref: "paper", x0: c.start + "-01", x1: c.end + "-01",
        y0: 0, y1: 1, fillcolor: "rgba(192,57,43,0.055)", line: { width: 0 }, layer: "below" });
      annotations.push({ xref: "x", yref: "paper", x: c.start + "-01", xanchor: "left", y: 1, yanchor: "top",
        text: c.name.split(" ")[0], showarrow: false, font: { size: 8.5, color: "rgba(160,45,33,0.8)" },
        bgcolor: "rgba(255,255,255,0.55)" });
    }
    return { shapes, annotations };
  }
  const endpointLabel = (x, y, text, color) => ({ xref: "x", yref: "y", x, y, xanchor: "left", xshift: 7,
    text: `<b>${text}</b>`, showarrow: false, font: { size: 9.5, color },
    bgcolor: "rgba(255,255,255,0.82)", bordercolor: color, borderpad: 2, borderwidth: 1 });

  // ---------- appbar / footer / nav ----------
  el("appbar-status").textContent = `window ${D.meta.window.start} → ${D.meta.window.end} · built ${D.meta.built}`;
  el("status-footer").innerHTML =
    `Generated by <b>Src/build_portfolios_dashboard_data.py</b> from ${D.meta.engines.join(", ")} · ` +
    `${D.meta.cost_note} · Window ${D.meta.window.start} → ${D.meta.window.end} (n=${D.meta.window.n}). ` +
    `All versions are in-sample research candidates — see the gates in §06.`;
  const tog = document.querySelector(".navtoggle");
  if (tog) tog.addEventListener("click", () => document.querySelector(".appnav").classList.toggle("open"));

  // ---------- KPI ribbon ----------
  el("kpi-ribbon").innerHTML = BOOK3.map((k) => {
    const m = M[k], hl = k === bestSharpe ? " kpi-perf" : "";
    return `<div class="kpi${hl}"><div class="kpi-label" style="color:${BOOKS[k].color}">
      ${BOOKS[k].label}</div>
      <div class="kpi-value">${p(m.cagr)} <span style="font-size:.8rem;font-weight:500;color:#6b7783">CAGR</span></div>
      <div class="kpi-sub">maxDD ${p(m.mdd)} · Sharpe ${m.sharpe.toFixed(2)} · vol ${p(m.vol)}</div></div>`;
  }).join("");

  // ---------- hero ----------
  const dd = (k) => M[k].mdd * 100;
  el("hero-verdict").innerHTML =
    `Fix the base <span class="arrow">→</span> buy return <span class="arrow">→</span> let MRS defend`;
  el("hero-thesis").innerHTML =
    `Five portfolios, each built for a different job rather than one book at five risk settings. ` +
    `<strong>${BOOKS[richest].label}</strong> compounds hardest (${p(M[richest].cagr)} a year), ` +
    `<strong>${BOOKS[shallowest].label}</strong> loses least (${p(M[shallowest].mdd)}), and ` +
    `<strong>${BOOKS[bestSharpe].label}</strong> carries the best risk-adjusted record ` +
    `(Sharpe ${M[bestSharpe].sharpe.toFixed(2)} against ${M[ANCHOR].sharpe.toFixed(2)} for the balanced ` +
    `benchmark). Only the DAA and Alpha act on the MRS regime; the rest hold their policy weights.`;
  el("hero-highlights").innerHTML = BOOK3.concat([ANCHOR]).map((k) => {
    const best = Math.max(...BOOK3.concat([ANCHOR]).map(dd)) === dd(k);
    return `<div class="hstat"><div class="hstat-v ${best ? "pos" : ""}">${p(M[k].mdd)}</div>
      <div class="hstat-l">${BOOKS[k].label} max drawdown</div></div>`;
  }).join("");

  // ---------- superseded reference ----------
  const R = D.reference;
  el("ref-note").innerHTML = `${R.note} Official numbers (${R.window}): CAGR ${p(R.metrics.cagr, 2)}, ` +
    `Sharpe ${R.metrics.sharpe.toFixed(2)}, maxDD ${p(R.metrics.mdd, 2)}. The legacy pages ` +
    `(Overview → Monte Carlo) still document that book until this family is ratified and cut over.`;

  // ---------- version cards ----------
  el("version-cards").innerHTML = BOOK3.map((k) => {
    const v = D.versions[k], m = M[k], c = BOOKS[k].color;
    const ddDelta = (m.mdd - M[ANCHOR].mdd) * 100;
    const dials = Object.entries(v.dials || {}).map(([lab, val]) => `${lab} ${val}`);
    const active = v.managed === "active";
    return `<div class="ev-card" style="--pc:${c}">
      <div class="ev-head"><span class="ev-name">${v.name}</span>
        <span class="ev-block" style="--bc:${c};background:${c}">${active ? "actively run" : "policy weights"}</span></div>
      <div class="ev-meta">${v.role}</div>
      <div class="ev-metric"><span class="ev-w">${p(m.cagr)}</span>
        <span class="ev-delta ${ddDelta >= 0 ? "pos" : "neg"}">maxDD ${fmtSign(ddDelta, "pp")} vs ${BOOKS[ANCHOR].label}</span></div>
      <div class="ev-holds">
        <span class="ev-hold">vol <b>${p(m.vol)}</b></span>
        <span class="ev-hold">Sharpe <b>${m.sharpe.toFixed(2)}</b></span>
        <span class="ev-hold">Calmar <b>${m.calmar.toFixed(2)}</b></span>
        <span class="ev-hold">β SPX <b>${m.beta_spx.toFixed(2)}</b></span></div>
      <div class="ev-holds">${dials.map((d) => `<span class="ev-hold">${d}</span>`).join("")}</div>
      <p class="ev-note">${v.thesis}</p>
      <div class="ev-cta" style="color:${active ? "var(--warn)" : "var(--accent)"}">${v.status} · ${v.horizon}</div>
    </div>`;
  }).join("");

  // ---------- allocation stacked bars ----------
  (function alloc() {
    const rows = BOOK3.map((k) => ({ key: k, w: D.versions[k].weights }))
      .concat([{ key: ANCHOR, w: { Equities: 0.6, FixedIncome: 0.4 } }]);
    const y = rows.map((r) => BOOKS[r.key].label);
    const traces = SLEEVES.map((s) => ({
      type: "bar", orientation: "h", name: SLEEVE_META[s].label,
      x: rows.map((r) => (r.w[s] || 0) * 100), y,
      marker: { color: SLEEVE_META[s].color, line: { color: "#fff", width: 2 } },
      text: rows.map((r) => ((r.w[s] || 0) >= 0.04 ? ((r.w[s]) * 100).toFixed(0) + "%" : "")),
      textposition: "inside", insidetextfont: { size: 10, color: "#fff" },
      hovertemplate: `${SLEEVE_META[s].label}: %{x:.1f}%<extra>%{y}</extra>`,
    }));
    Plotly.newPlot("alloc-chart", traces, { ...BASE, barmode: "stack",
      margin: { l: 80, r: 10, t: 6, b: 26 },
      legend: { orientation: "h", y: -0.14, font: { size: 10 }, traceorder: "normal" },
      xaxis: { ...BASE.xaxis, ticksuffix: "%", range: [0, 100] },
      yaxis: { ...BASE.yaxis, autorange: "reversed" } }, CFG);
    const e = D.versions.endowment.weights, s = D.versions.saa.weights;
    el("alloc-read").innerHTML =
      `Moving the governor 82→88% is <strong>buy equities, sell fixed income</strong>: equities ` +
      `${(e.Equities * 100).toFixed(1)}→${(s.Equities * 100).toFixed(1)}%, FI ${(e.FixedIncome * 100).toFixed(1)}→` +
      `${(s.FixedIncome * 100).toFixed(1)}%, while commodities stay near the 10% ceiling in both — the ` +
      `governor is what funds real diversifiers instead of concentrating. Equity weights are ` +
      `<strong>optimizer output</strong> (endogenous), not hand-set numbers.`;
  })();

  // ---------- FI decomposition ----------
  (function fi() {
    const legs = ["Govt", "IG", "TIPS", "HY"];
    const cols = BOOK3.filter((k) => Object.values(D.versions[k].fi_of_book || {}).some((v) => v > 0.0005));
    const rows = legs.map((l) => {
      const cells = cols.map((k) => {
        const v = (D.versions[k].fi_of_book[l] || 0) * 100;
        return `<td class="num">${v > 0.05 ? v.toFixed(1) + "%" : "<span class=\"z\">–</span>"}</td>`;
      }).join("");
      return `<tr><td class="strong">${l}</td>${cells}</tr>`;
    }).join("");
    el("fi-table").innerHTML = `<table class="dtbl"><thead><tr><th>Fixed income leg (% of portfolio)</th>` +
      cols.map((k) => `<th class="num">${BOOKS[k].label}</th>`).join("") +
      `</tr></thead><tbody>${rows}</tbody></table>`;
  })();

  // ---------- DAA regime → book map ----------
  (function daMap() {
    const T = D.da.timeline, cur = T.state[T.state.length - 1];
    const trend = D.da.trend_by_state || {};
    el("da-map").innerHTML = REGIMES.map((rg) => {
      const t = D.da.class_tilt[rg] || {};
      const eqT = t.Equities || 0, fiT = t.FixedIncome || 0;
      const tr = trend[rg];
      const months = (D.da.months_in_state || {})[rg] || 0;
      return `<div class="scn ${rg === cur ? "cur" : ""}">
        ${rg === cur ? '<span class="badge">now</span>' : ""}
        <div class="scn-regime">${rg}</div>
        <div class="scn-stance">${REGIME_STANCE[rg]} · equities ${fmtSign(eqT, "pp")} · bonds ${fmtSign(fiT, "pp")}</div>
        <div class="scn-bar"><span style="width:${Math.min(Math.abs(eqT) * 6, 100)}%"></span></div>
        <div class="scn-meta">${tr != null ? `trend sleeve ${(tr * 100).toFixed(1)}% · ` : ""}${months} months observed</div>
      </div>`;
    }).join("");
    el("da-map-read").innerHTML =
      `The regime is <strong>not decided here</strong>: it is the confirmed <strong>MRS</strong> state on a ` +
      `one-month lag, and what each state implies for allocation comes from the Playbook's own regime ` +
      `books rather than a second opinion. Over the window MRS changed state ` +
      `<strong>${D.da.switches} times</strong> (~${(D.da.switches / (D.meta.window.n / 12)).toFixed(1)}/yr); ` +
      `the DAA runs ~${(D.da.turnover_oneway_yr * 100).toFixed(0)}% one-way turnover a year, roughly ` +
      `${D.da.cost_drag_bp_yr.toFixed(0)}bp of cost drag (all results net). Current regime: ` +
      `<strong>${cur}</strong>. Only the DAA and Alpha act on it — the three strategic portfolios hold ` +
      `their policy weights by design.`;
  })();

  // ---------- growth of $1 (rebase chips) ----------
  const REBASE = [["Inception", 0], ["2010", "2010-01"], ["2015", "2015-01"], ["2020", "2020-01"], ["2022", "2022-01"]];
  let rebaseIdx = 0;
  function drawGrowth() {
    const i0 = rebaseIdx;
    const traces = [], ann = [];
    for (const k of BOOK3.concat(["spy", ANCHOR])) {
      const r = D.series.returns[k];
      const nav = []; let v = 1;
      for (let i = i0; i < r.length; i++) { v *= 1 + (r[i] || 0); nav.push(v); }
      const xs = dates.slice(i0);
      const main = BOOK3.includes(k);
      traces.push({ type: "scatter", mode: "lines", name: BOOKS[k].label, x: xs, y: nav,
        line: { color: BOOKS[k].color, width: main ? 2.2 : 1.4, dash: main ? "solid" : "dot" },
        opacity: k === "spy" ? 0.75 : 1,
        hovertemplate: `${BOOKS[k].label}: $%{y:.2f}<extra>%{x|%b %Y}</extra>` });
      ann.push(endpointLabel(xs[xs.length - 1], nav[nav.length - 1], `$${nav[nav.length - 1].toFixed(2)}`, BOOKS[k].color));
    }
    // rank-sort endpoint labels to reduce overlap
    ann.sort((a, b) => a.y - b.y).forEach((a, i, arr) => { if (i && a.y / arr[i - 1].y < 1.06) a.yshift = 10; });
    const ov = crisisOverlay();
    Plotly.react("growth-chart", traces, { ...BASE, margin: { l: 44, r: 62, t: 8, b: 30 },
      legend: { orientation: "h", y: 1.08, font: { size: 10 } },
      shapes: ov.shapes, annotations: ov.annotations.concat(ann),
      yaxis: { ...BASE.yaxis, tickprefix: "$", exponentformat: "none" } }, CFG);
    el("growth-sub").textContent = `rebased to $1 at ${D.series.dates[i0]} · DAA net of cost`;
    const endv = (k) => { let v = 1; const r = D.series.returns[k]; for (let i = i0; i < r.length; i++) v *= 1 + (r[i] || 0); return v; };
    el("growth-read").innerHTML =
      `From ${D.series.dates[i0]}: ` +
      BOOK3.map((k) => `${BOOKS[k].label} <strong>$${endv(k).toFixed(2)}</strong>`).join(" · ") +
      ` · ${BOOKS[ANCHOR].label} $${endv(ANCHOR).toFixed(2)} · S&P 500 $${endv("spy").toFixed(2)}. ` +
      `The S&P compounds fastest and draws down ${p(M.spy.mdd)} doing it — the family's question is what ` +
      `each dollar of return costs in tail risk, answered in §04.`;
  }
  el("growth-controls").innerHTML = REBASE.map(([lab, from], i) =>
    `<span class="chip clickable ${i === 0 ? "sel" : ""}" data-from="${from}">${lab}</span>`).join("");
  el("growth-controls").querySelectorAll(".chip").forEach((ch) => ch.addEventListener("click", () => {
    el("growth-controls").querySelectorAll(".chip").forEach((c) => c.classList.remove("sel"));
    ch.classList.add("sel");
    const f = ch.dataset.from;
    rebaseIdx = f === "0" ? 0 : Math.max(0, D.series.dates.indexOf(f));
    drawGrowth();
  }));
  drawGrowth();

  // ---------- metric panel ----------
  (function metricTable() {
    const rows = [
      ["CAGR", "cagr", "pct", +1], ["Volatility", "vol", "pct", -1], ["Sharpe", "sharpe", "num", +1],
      ["Sortino", "sortino", "num", +1], ["CVaR 5%", "cvar5", "pct", +1], ["Max drawdown", "mdd", "pct", +1],
      ["Calmar", "calmar", "num", +1], ["β S&P 500", "beta_spx", "num", 0], ["β 60/40", "beta_6040", "num", 0],
      ["TE vs 60/40", "te_6040", "pct", 0], ["Downside deviation", "downside_dev", "pct", -1],
    ];
    const cols = BOOK3.concat([ANCHOR, "spy"]);
    const body = rows.map(([lab, key, kind, dir]) => {
      const vals = cols.map((k) => M[k][key]);
      let best = -1;
      if (dir !== 0) {
        const cand = BOOK3.map((k) => M[k][key]).map((v, i) => [v == null ? (dir > 0 ? -1e9 : 1e9) : v * dir, i]);
        best = cand.sort((a, b) => b[0] - a[0])[0][1];
      }
      const cells = vals.map((v, i) => {
        const s = v == null ? "—" : kind === "pct" ? p(v) : v.toFixed(2);
        const hl = i === best ? ' style="background:#eef5fb;font-weight:700;color:#0e2233"' : "";
        return `<td class="num"${hl}>${s}</td>`;
      }).join("");
      return `<tr><td>${lab}</td>${cells}</tr>`;
    }).join("");
    el("metric-table").innerHTML = `<table class="dtbl"><thead><tr><th>Metric</th>` +
      cols.map((k) => `<th class="num" style="color:${BOOKS[k].color}">${BOOKS[k].label}</th>`).join("") +
      `</tr></thead><tbody>${body}</tbody></table>`;
  })();

  // ---------- drawdown ----------
  (function ddChart() {
    const traces = [ANCHOR].concat(BOOK3).map((k) => {
      const r = D.series.returns[k];
      let v = 1, peak = 1; const ddv = [];
      for (let i = 0; i < r.length; i++) { v *= 1 + (r[i] || 0); peak = Math.max(peak, v); ddv.push((v / peak - 1) * 100); }
      return { type: "scatter", mode: "lines", name: BOOKS[k].label, x: dates, y: ddv,
        line: { color: BOOKS[k].color, width: k === ANCHOR ? 1.2 : 1.9, dash: k === ANCHOR ? "dot" : "solid" },
        fill: k === ANCHOR ? "tozeroy" : "none", fillcolor: "rgba(214,138,19,0.07)",
        hovertemplate: `${BOOKS[k].label}: %{y:.1f}%<extra>%{x|%b %Y}</extra>` };
    });
    const ov = crisisOverlay();
    Plotly.newPlot("dd-chart", traces, { ...BASE, legend: { orientation: "h", y: 1.12, font: { size: 10 } },
      shapes: ov.shapes, annotations: ov.annotations,
      yaxis: { ...BASE.yaxis, ticksuffix: "%" } }, CFG);
    el("dd-read").innerHTML =
      `Where the portfolios separate: ` +
      BOOK3.map((k) => `${BOOKS[k].label} ${p(M[k].mdd)}`).join(" · ") +
      `, against ${p(M[ANCHOR].mdd)} for the balanced benchmark. The actively run book sheds ` +
      `<strong>${fmtSign((M.daa.mdd - M.saa.mdd) * 100, "pp")}</strong> of drawdown against the same ` +
      `holdings untilted — the engines are paid in tail shape, not in steady return.`;
  })();

  // ---------- calendar-year returns ----------
  (function annual() {
    const years = {};
    D.series.dates.forEach((d, i) => { const y = d.slice(0, 4); (years[y] = years[y] || []).push(i); });
    const ys = Object.keys(years).sort();
    const keys = BOOK3.concat([ANCHOR]);
    const traces = keys.map((k) => ({
      type: "bar", name: BOOKS[k].label,
      x: ys, y: ys.map((y) => (years[y].reduce((a, i) => a * (1 + (D.series.returns[k][i] || 0)), 1) - 1) * 100),
      marker: { color: BOOKS[k].color, opacity: k === "6040" ? 0.55 : 0.92 },
      hovertemplate: `${BOOKS[k].label} %{x}: %{y:.1f}%<extra></extra>`,
    }));
    Plotly.newPlot("annual-chart", traces, { ...BASE, barmode: "group", bargap: 0.25, bargroupgap: 0.06,
      legend: { orientation: "h", y: 1.12, font: { size: 10 } },
      yaxis: { ...BASE.yaxis, ticksuffix: "%", zeroline: true, zerolinecolor: "#c5cfd9" } }, CFG);
    const first = ys[0], last = ys[ys.length - 1];
    el("annual-read").innerHTML = `${first} and ${last} are partial years (window ${D.meta.window.start} → ` +
      `${D.meta.window.end}). 2022 is the honest test of the family: every duration-heavy book loses; the ` +
      `defense that works there is commodities and short duration — the two-axis DA refinement (§05).`;
  })();

  // ---------- crisis episodes ----------
  (function crisis() {
    const keys = BOOK3.concat([ANCHOR]);
    const traces = keys.map((k) => ({
      type: "bar", orientation: "h", name: BOOKS[k].label,
      y: D.crises.map((c) => c.name).reverse(),
      x: D.crises.map((c) => c.returns[k] * 100).reverse(),
      marker: { color: BOOKS[k].color, opacity: k === "6040" ? 0.55 : 0.92 },
      hovertemplate: `${BOOKS[k].label}: %{x:.1f}%<extra>%{y}</extra>`,
    }));
    Plotly.newPlot("crisis-chart", traces, { ...BASE, barmode: "group", bargap: 0.22, bargroupgap: 0.05,
      margin: { l: 96, r: 12, t: 6, b: 28 }, legend: { orientation: "h", y: 1.12, font: { size: 10 } },
      xaxis: { ...BASE.xaxis, type: "linear", ticksuffix: "%", zeroline: true, zerolinecolor: "#c5cfd9" },
      yaxis: { ...BASE.yaxis, type: "category" } }, CFG);

    const wins = {};
    BOOK3.forEach((k) => { wins[k] = 0; });
    const rows = D.crises.map((c) => {
      const b = c.returns[ANCHOR];
      BOOK3.forEach((k) => { if (c.returns[k] > b) wins[k]++; });
      const cell = (k) => {
        const v = c.returns[k] * 100, beat = c.returns[k] > b && k !== ANCHOR;
        return `<td class="num ${v >= 0 ? "pos" : "neg"}"${beat ? ' style="font-weight:700"' : ""}>${fmtPct(v)}</td>`;
      };
      return `<tr><td>${c.name}<div class="sub">${c.start} → ${c.end}</div></td>` +
        BOOK3.concat([ANCHOR]).map(cell).join("") + `</tr>`;
    }).join("");
    el("crisis-table").innerHTML = `<table class="dtbl"><thead><tr><th>Episode</th>` +
      BOOK3.concat([ANCHOR]).map((k) => `<th class="num" style="color:${BOOKS[k].color}">${BOOKS[k].label}</th>`).join("") +
      `</tr></thead><tbody>${rows}</tbody></table>`;
    const bestC = BOOK3.reduce((a, b2) => (wins[b2] > wins[a] ? b2 : a));
    el("crisis-read").innerHTML =
      `Against the balanced benchmark across ${D.crises.length} episodes: ` +
      BOOK3.map((k) => `${BOOKS[k].label} ${wins[k]}/${D.crises.length}`).join(" · ") +
      `. <strong>${BOOKS[bestC].label}</strong> holds up most often (bold = beats the benchmark in that ` +
      `episode). 2022 is the honest test — every duration-carrying portfolio loses; what separates them is ` +
      `how much.`;
  })();

  // ---------- regime timeline ----------
  (function regime() {
    const t = D.da.timeline;
    const xs = t.dates.map((d) => d + "-01");
    // contiguous regime blocks as background shapes
    const shapes = [];
    let s0 = 0;
    for (let i = 1; i <= t.state.length; i++) {
      if (i === t.state.length || t.state[i] !== t.state[s0]) {
        shapes.push({ type: "rect", xref: "x", yref: "paper", x0: xs[s0], x1: xs[Math.min(i, xs.length - 1)],
          y0: 0, y1: 1, fillcolor: REGIME_SHADE[t.state[s0]] || "rgba(0,0,0,0)", line: { width: 0 }, layer: "below" });
        s0 = i;
      }
    }
    const legendDummies = REGIMES.map((rg) => ({ type: "scatter", mode: "markers", name: rg,
      x: [xs[0]], y: [0], visible: "legendonly", hoverinfo: "skip",
      marker: { symbol: "square", size: 10, color: REGIME_SHADE[rg].replace(/0\.\d+\)/, "0.8)") } }));
    Plotly.newPlot("regime-chart", [{
      type: "scatter", mode: "lines", name: "MRS composite", x: xs, y: t.composite,
      line: { color: "#0e2233", width: 1.8 },
      hovertemplate: "MRS %{y:.2f}<extra>%{x|%b %Y}</extra>",
    }].concat(legendDummies), { ...BASE, shapes,
      legend: { orientation: "h", y: 1.14, font: { size: 10 } }, showlegend: true,
      yaxis: { ...BASE.yaxis, zeroline: true, zerolinecolor: "#c5cfd9",
        title: { text: "MRS composite", font: { size: 10 } } } }, CFG);
    const counts = REGIMES.map((rg) => `${rg} ${t.state.filter((s) => s === rg).length}m`).join(" · ");
    const tr = D.da.trend_by_state || {};
    el("regime-read").innerHTML =
      `The line is the <strong>MRS composite</strong> and the shading its confirmed regime — the platform's ` +
      `own backbone signal, read on a one-month lag, not a regime view formed in the portfolio layer. ` +
      `Months per regime: ${counts}. What the portfolios do with it: the diversifier sleeve runs ` +
      (Object.keys(tr).length
        ? REGIMES.filter((r) => tr[r] != null).map((r) => `${(tr[r] * 100).toFixed(1)}% in ${r}`).join(", ")
        : "larger as conditions deteriorate") +
      `, and the class tilt for each state comes from the Playbook's regime books. MRS begins 2003-08, so ` +
      `the regime engine contributes nothing before then.`;
  })();

  // ---------- rotation value isolated ----------
  (function rotation() {
    const book = M.daa, base = M.saa;
    if (!book || !base) { el("rotation-read").textContent = ""; return; }
    const cats = ["CAGR", "Max drawdown"];
    const mk = (nm, m, color) => ({ type: "bar", name: nm, x: cats, y: [m.cagr * 100, m.mdd * 100],
      marker: { color }, text: [p(m.cagr), p(m.mdd)], textposition: "auto", textfont: { size: 10.5 },
      hovertemplate: `${nm}: %{y:.1f}%<extra></extra>` });
    Plotly.newPlot("rotation-chart", [
      mk("DAA — run actively (net)", book, BOOKS.daa.color),
      mk("SAA — same book, untilted", base, BOOKS.saa.color),
    ], { ...BASE, barmode: "group", bargap: 0.35, legend: { orientation: "h", y: 1.16, font: { size: 10 } },
      xaxis: { ...BASE.xaxis, type: "category" },
      yaxis: { ...BASE.yaxis, ticksuffix: "%", zeroline: true, zerolinecolor: "#c5cfd9" } }, CFG);
    el("rotation-read").innerHTML =
      `The same holdings, with and without the engines: the DAA keeps the return ` +
      `(${p(book.cagr)} vs ${p(base.cagr)}) and removes <strong>${fmtSign((book.mdd - base.mdd) * 100, "pp")} ` +
      `of max drawdown</strong>, lifting Sharpe ${base.sharpe.toFixed(2)} → <strong>${book.sharpe.toFixed(2)}</strong>. ` +
      `The value is tail-shaping, not steady alpha.`;
  })();

  // ---------- caveats + gates ----------
  el("da-caveats").innerHTML = D.da.caveats.map((c) => {
    const i = c.indexOf(":");
    if (i > 0 && i < 60) return `<div class="flagc"><b>${c.slice(0, i)}</b><span>${c.slice(i + 1)}</span></div>`;
    return `<div class="flagc"><span>${c}</span></div>`;
  }).join("");

  el("gates-table").innerHTML = `<table class="dtbl"><thead><tr><th style="width:110px">Owner</th>
    <th>Gate</th></tr></thead><tbody>` + D.gates.map((g) =>
    `<tr><td class="strong">${g.owner}</td><td>${g.item}</td></tr>`).join("") + `</tbody></table>`;
  el("gates-read").innerHTML =
    `Everything on this page is computed on one in-sample window (${D.meta.window.start} → ` +
    `${D.meta.window.end}); no version has passed a walk-forward yet. The next research pass rebuilds the ` +
    `family around <strong>four regime-optimized portfolios</strong> (boundaries learned from optimized ` +
    `movement across regimes, DA moving between them on MRS) — these candidates are the current best ` +
    `evidence, not the final family.`;
})();
